{
  "implementation": "def solve(case):
    threshold = case.get('threshold')
    if threshold is None:
        raise ValueError('missing threshold')
    calls = case.get('calls')
    if not isinstance(calls, list):
        raise ValueError('calls must be a list')
    accepted_call_ids = []
    diagnostics = []
    for c in calls:
        call_id = c.get('call_id')
        if call_id is None:
            raise ValueError('call missing call_id')
        loss_without = c.get('loss_without_call')
        loss_with = c.get('loss_with_call')
        pred_tokens = c.get('prediction_tokens')
        parseable = c.get('parseable')
        if any(v is None for v in [loss_without, loss_with, pred_tokens, parseable]):
            raise ValueError('call missing required field')
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        accepted = bool(parseable) and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': round(normalized_gain, 8)
        })
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
